/*
 * STM32 implementation of bsp/board_io.h on top of the STM32CubeMX HAL.
 *
 * main.h is generated by STM32CubeMX. The status output is the GPIO whose
 * CubeMX user label is given by the CMake cache variable FW_STATUS_LED
 * (default STATUS_LED), i.e. <label>_Pin and <label>_GPIO_Port; no pin is
 * assumed here.
 *
 * Call bsp_heartbeat_task() from a USER CODE section of the generated main loop.
 */
#include "main.h"

#include "app/heartbeat.h"
#include "bsp/board_io.h"

#ifndef BSP_STATUS_LED
#define BSP_STATUS_LED STATUS_LED
#endif
#define BSP_CAT2(a, b) a##b
#define BSP_CAT(a, b) BSP_CAT2(a, b)
/* A compile error naming <label>_Pin means FW_STATUS_LED does not match a CubeMX GPIO label. */
#define STATUS_LED_PIN BSP_CAT(BSP_STATUS_LED, _Pin)
#define STATUS_LED_PORT BSP_CAT(BSP_STATUS_LED, _GPIO_Port)

static uint32_t stm32_millis(void *ctx)
{
    (void)ctx;
    return HAL_GetTick();
}

static bool stm32_set_status(void *ctx, bool on)
{
    (void)ctx;
    HAL_GPIO_WritePin(STATUS_LED_PORT, STATUS_LED_PIN, on ? GPIO_PIN_SET : GPIO_PIN_RESET);
    return true;
}

static const board_io_t stm32_io = {.millis = stm32_millis, .set_status = stm32_set_status, .ctx = 0};
static heartbeat_t heartbeat;
static bool started;

void bsp_heartbeat_task(void)
{
    if (!started) {
        started = heartbeat_init(&heartbeat, &stm32_io, 1000u, 200u) == HEARTBEAT_OK;
        return;
    }
    (void)heartbeat_poll(&heartbeat);
}
